function validate([board]) {
  if (!Array.isArray(board) || board.length !== 8) return 'board must have exactly 8 rows.';
  if (board.some(row => !Array.isArray(row) || row.length !== 8)) return 'Every row must have exactly 8 cells.';
  if (board.some(row => row.some(cell => !['R', 'B', 'p', '.'].includes(cell)))) return "Each cell is 'R', 'B', 'p' or '.'.";
  const rooks = board.reduce((sum, row) => sum + row.filter(cell => cell === 'R').length, 0);
  if (rooks !== 1) return "The board needs exactly one 'R'.";
  return null;
}

