function numRookCaptures(board) {
  let rookRow = 0;
  let rookCol = 0;
  for (let row = 0; row < 8; row++) {
    for (let col = 0; col < 8; col++) {
      if (board[row][col] === 'R') {
        rookRow = row;
        rookCol = col;
      }
    }
  }

  const directions = [[-1, 0], [1, 0], [0, -1], [0, 1]];
  let captures = 0;
  for (const [dr, dc] of directions) {
    let row = rookRow + dr;
    let col = rookCol + dc;
    while (row >= 0 && row < 8 && col >= 0 && col < 8) {
      const piece = board[row][col];
      if (piece === 'p') {
        captures++;
      }
      if (piece !== '.') {
        break;
      }
      row += dr;
      col += dc;
    }
  }
  return captures;
}

