function numRookCaptures(board) {
  // For every pawn sharing a line with the rook, check that every square strictly between them is empty.
  let rr = -1, rc = -1;
  board.forEach((line, r) => line.forEach((cell, c) => { if (cell === 'R') { rr = r; rc = c; } }));
  let total = 0;
  for (let r = 0; r < 8; r++) {
    for (let c = 0; c < 8; c++) {
      if (board[r][c] !== 'p' || (r !== rr && c !== rc)) continue;
      const between = [];
      if (r === rr) for (let k = Math.min(c, rc) + 1; k < Math.max(c, rc); k++) between.push(board[r][k]);
      else for (let k = Math.min(r, rr) + 1; k < Math.max(r, rr); k++) between.push(board[k][c]);
      if (between.every(cell => cell === '.')) total++;
    }
  }
  return total;
}

