function generate(rand, size) {
  const board = Array.from({ length: 8 }, () => new Array(8).fill('.'));
  // The board is always 8 x 8; "large" boards are simply busier.
  const density = size === 'large' ? 0.3 + rand() * 0.5 : rand() * 0.6;
  const pawnShare = rand();
  for (let r = 0; r < 8; r++) {
    for (let c = 0; c < 8; c++) {
      if (rand() < density) board[r][c] = rand() < pawnShare ? 'p' : 'B';
    }
  }
  board[Math.floor(rand() * 8)][Math.floor(rand() * 8)] = 'R';
  return [board];
}
